-- All seven sheets of the supplied demo workbook preserved as immutable rows.
-- Rows in this schema ARE NOT additional military_core entities. Don't sum across layers.
CREATE TABLE refdata.workbook_sheet (sheet_name text PRIMARY KEY, record_kind text NOT NULL, is_demo_model boolean NOT NULL, title text, note text, columns jsonb NOT NULL, imported_on timestamptz NOT NULL DEFAULT now());
CREATE TABLE refdata.workbook_row (row_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sheet_name text NOT NULL REFERENCES refdata.workbook_sheet(sheet_name), source_row int NOT NULL, record_kind text NOT NULL, is_demo_model boolean NOT NULL, payload jsonb NOT NULL, UNIQUE(sheet_name,source_row));
CREATE INDEX ON refdata.workbook_row(record_kind);
CREATE INDEX ON refdata.workbook_row USING gin(payload);
-- Presentation-only views: all figures remain labelled as demo values, never independent counts.
CREATE VIEW registry_api.demo_excel_positions AS SELECT source_row, payload->>'Формирование' AS formation, payload->>'Код подразделения' AS unit_code, payload->>'Путь подразделения' AS unit_path, payload->>'Должность модели' AS position_name, payload->>'Звание модели' AS rank_name, NULLIF(payload->>'Мест в модели','')::int AS model_slots FROM refdata.workbook_row WHERE record_kind='demo_positions';
CREATE VIEW registry_api.demo_excel_headcounts AS SELECT source_row, payload->>'Формирование' AS formation, payload->>'Код подразделения' AS unit_code, payload->>'Путь подразделения' AS unit_path, payload->>'Уровень' AS level_name, NULLIF(payload->>'Собственных мест','')::int AS own_slots, NULLIF(payload->>'Мест с подчинёнными','')::int AS aggregate_slots, payload->>'Статус' AS data_status FROM refdata.workbook_row WHERE record_kind='demo_headcounts';
CREATE VIEW registry_api.demo_excel_assets AS SELECT source_row, payload->>'Формирование' AS formation, payload->>'Код подразделения' AS unit_code, payload->>'Путь подразделения' AS unit_path, payload->>'Имущество модели' AS item_name, NULLIF(payload->>'Количество','')::numeric AS model_qty, payload->>'Ед.' AS unit_measure, payload->>'Регистр' AS register_name FROM refdata.workbook_row WHERE record_kind='demo_assets';
COMMENT ON TABLE refdata.workbook_row IS 'All seven workbook sheets; the three DEMO sheets duplicate/reconcile the full model, not independent figures for addition.';
COMMENT ON VIEW registry_api.demo_excel_assets IS 'Three model asset registers, NOT additive; filter by register_name.';
